## 4️⃣ Sample Minimal Code (Node) – One‑Shot Run

Below is a **single‑file script** you can drop on any Linux VM. It pulls a random AI‑news headline, generates a script, TTS, images, assembles a video, uploads to YouTube, and logs the result.

```js
// filename: run_one_cycle.js
// Install deps first: npm i rss-parser openai googleapis node-fetch@2
const Parser = require('rss-parser');
const { Configuration, OpenAIApi } = require('openai');
const { google } = require('googleapis');
const fetch = require('node-fetch');
const { execSync } = require('child_process');
const fs = require('fs');
require('dotenv').config();   // .env holds API keys

// ---------- 1️⃣ Pull a headline ----------
const parser = new Parser();
async function getHeadline() {
  const feed = await parser.parseURL('https://feeds.feedburner.com/TechCrunch/ai');
  const item = feed.items[Math.floor(Math.random() * feed.items.length)];
  return item.title.replace(/[\\|"']/g, '');
}

// ---------- 2️⃣ Generate script ----------
async function genScript(topic) {
  const cfg = new Configuration({ apiKey: process.env.OPENAI_API_KEY });
  const openai = new OpenAIApi(cfg);
  const prompt = `Write a 6‑minute YouTube script about "${topic}". Include a hook, three concise points, and a short call‑to‑action. Use natural language, no markdown.`;
  const resp = await openai.createChatCompletion({
    model: 'gpt-4o-mini',
    messages: [{ role: 'user', content: prompt }],
    temperature: 0.7,
  });
  return resp.data.choices[0].message.content.trim();
}

// ---------- 3️⃣ TTS ----------
async function tts(text, outPath) {
  const url = 'https://api.elevenlabs.io/v1/text-to-speech/EXAMPLE_VOICE_ID';
  const r = await fetch(url, {
    method: 'POST',
    headers: {
      'xi-api-key': process.env.ELEVENLABS_API_KEY,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ text, voice_settings: { stability: 0.75, similarity_boost: 0.85 } }),
  });
  const buffer = await r.buffer();
  fs.writeFileSync(outPath, buffer);
}

// ---------- 4️⃣ Image generation (Stable Diffusion) ----------
function genImages(topic, count = 10) {
  for (let i = 1; i <= count; i++) {
    const prompt = `${topic} illustration, vibrant, cinematic, 16:9`;
    // You can replace with your own txt2img wrapper (e.g., `sdxl.py`)
    execSync(`python3 sdxl_generate.py --prompt "${prompt}" --out img_${i}.png`);
  }
}

// ---------- 5️⃣ Assemble video ----------
function makeVideo(audioPath, outVideo) {
  const imgPattern = 'img_%d.png';
  execSync(`ffmpeg -framerate 0.25 -i ${imgPattern} -i ${audioPath} -c:v libx264 -r 30 -pix_fmt yuv420p -c:a aac ${outVideo}`);
}

// ---------- 6️⃣ Upload to YouTube ----------
async function upload(videoFile, title, description, tags) {
  const auth = new google.auth.GoogleAuth({
    keyFile: 'gcp_service_account.json',
    scopes: ['https://www.googleapis.com/auth/youtube.upload'],
  });
  const youtube = google.youtube({ version: 'v3', auth });
  const res = await youtube.videos.insert({
    part: 'snippet,status',
    requestBody: {
      snippet: { title, description, tags },
      status: { privacyStatus: 'public' },
    },
    media: { body: fs.createReadStream(videoFile) },
  });
  const videoId = res.data.id;
  // thumbnail
  await youtube.thumbnails.set({
    videoId,
    media: { body: fs.createReadStream('thumb.jpg') },
  });
  return videoId;
}

// ---------- Main ----------
(async () => {
  const headline = await getHeadline();
  console.log('🔎 Headline:', headline);
  const script = await genScript(headline);
  fs.writeFileSync('script.txt', script);
  console.log('📝 Script generated');

  await tts(script, 'voice.mp3');
  console.log('🔊 TTS done');

  genImages(headline);
  console.log('🖼 Images generated');

  makeVideo('voice.mp3', 'final.mp4');
  console.log('🎞 Video assembled');

  // Very naive thumbnail – you can replace with Midjourney later
  execSync('convert -size 1280x720 xc:black -gravity center -pointsize 48 -fill white -annotate 0 "AI Tips" thumb.jpg');

  const videoId = await upload('final.mp4', headline, script, [headline.split(' ')[0], 'AI', 'Tutorial']);
  console.log('🚀 Uploaded! Video ID:', videoId);
})();
```

